// Pseudo-test: verify policy reloads propagate within short window
async function testPolicyPropagation(nodePool, policyApi) {
  await policyApi.forceUpdate();
  const results = await Promise.all(nodePool.map(n => n.getCurrentPolicyVersion()));
  return results.every(v => v === results[0]);
}
